   int percolate_down(int pos, double val)
   {
      while (2*pos+1 < c.size())
      {
         int left = 2*pos+1;
         int right = left+1;
         int tgt;
         if (right < c.size() && w[c[right]] < w[c[left]]) { tgt = right; }
         else { tgt = left; }
         if (w[c[tgt]] < val)
         {
            c[pos] = c[tgt];
            loc[c[tgt]] = pos;
            pos = tgt;
         }
         else
         {
            break;
         }
      }
      return pos;
   }

   void push(int i)
   {
      double val = w[i];
      c.push_back(-1);
      int pos = c.size()-1;
      pos = percolate_up(pos, val);
      c[pos] = i;
      loc[i] = pos;
