 {
    MFEM_ASSERT(IsVariableOrder(), "");
    MFEM_ASSERT(edge_dof.Size() == mesh->GetNEdges() + 1, "");

    const int *beg = edge_dof.GetRow(edge);
    const int *end = edge_dof.GetRow(edge + 1); // terminator, see above

    while (beg < end)
