+        /// Returns the gradients of the LSF for point x.
+        template<typename T>
+        blitz::TinyVector<T,3> grad(const blitz::TinyVector<T,3>& x) const
+        {
+            int el_order=el->GetOrder();
+            T u1[el_order+1];
+            T u2[el_order+1];
+            T u3[el_order+1];
