void FiniteElementSpace::UpdateNURBS()
{
   MFEM_VERIFY(NURBSext, "NURBSExt not defined.");

   nvdofs = 0;
   nedofs = 0;
   nfdofs = 0;
   nbdofs = 0;
   bdofs = NULL;

   delete face_dof;
   face_dof = NULL;
   face_to_be.DeleteAll();

   dynamic_cast<const NURBSFECollection *>(fec)->Reset();

   if (dynamic_cast<const NURBS_HDivFECollection *>(fec))
   {
      if (mesh->Dimension() == 2)
      {
         Array<int> newOrders1 = NURBSext->GetOrders();
         Array<int> newOrders2 = NURBSext->GetOrders();

         newOrders1[0] += 1;
         newOrders2[1] += 1;

         newOrders1.Print();
         newOrders2.Print();

         scalar_ext.SetSize(2);
         scalar_fec.SetSize(2);
         scalar_fes.SetSize(2);

         scalar_ext[0] = new NURBSExtension(NURBSext, newOrders1);
         scalar_ext[1] = new NURBSExtension(NURBSext, newOrders2);

         scalar_fec[0]  = new NURBSFECollection();
         scalar_fec[1]  = new NURBSFECollection();

         scalar_fes[0] = new FiniteElementSpace(mesh, scalar_ext[0], scalar_fec[0]);
         scalar_fes[1] = new FiniteElementSpace(mesh, scalar_ext[1], scalar_fec[1]);

         int ndofs1 = scalar_ext[0]->GetNDof();

         ndofs = scalar_ext[0]->GetNDof()
                 + scalar_ext[1]->GetNDof();

         // Merge Tables
         elem_dof = new Table(*scalar_ext[0]->GetElementDofTable(),
                              *scalar_ext[1]->GetElementDofTable(),ndofs1 );

         bdr_elem_dof = new Table(*scalar_ext[0]->GetBdrElementDofTable(),
                                  *scalar_ext[1]->GetBdrElementDofTable(),ndofs1,
                                  false );
      }
      else if (mesh->Dimension() == 3)
      {
         Array<int> newOrders0 = NURBSext->GetOrders();
         Array<int> newOrders1 = NURBSext->GetOrders();
         Array<int> newOrders2 = NURBSext->GetOrders();

         newOrders0[0] += 1;
         newOrders1[1] += 1;
         newOrders2[2] += 1;

         newOrders0.Print();
         newOrders1.Print();
         newOrders2.Print();

         scalar_ext.SetSize(3);
         scalar_fec.SetSize(3);
         scalar_fes.SetSize(3);

         scalar_ext[0] = new NURBSExtension(NURBSext, newOrders0);
         scalar_ext[1] = new NURBSExtension(NURBSext, newOrders1);
         scalar_ext[2] = new NURBSExtension(NURBSext, newOrders2);

         scalar_fec[0]  = new NURBSFECollection();
         scalar_fec[1]  = new NURBSFECollection();
         scalar_fec[2]  = new NURBSFECollection();

         scalar_fes[0] = new FiniteElementSpace(mesh, scalar_ext[0], scalar_fec[0]);
         scalar_fes[1] = new FiniteElementSpace(mesh, scalar_ext[1], scalar_fec[1]);
         scalar_fes[2] = new FiniteElementSpace(mesh, scalar_ext[2], scalar_fec[2]);

         int ndofs1 = scalar_ext[0]->GetNDof();
         int ndofs2 = scalar_ext[0]->GetNDof() +
                      scalar_ext[1]->GetNDof();

         ndofs = scalar_ext[0]->GetNDof() +
                 scalar_ext[1]->GetNDof() +
                 scalar_ext[2]->GetNDof();

         // Merge Tables
         elem_dof = new Table(*scalar_ext[0]->GetElementDofTable(),
                              *scalar_ext[1]->GetElementDofTable(),ndofs1,
                              *scalar_ext[2]->GetElementDofTable(),ndofs2);

         bdr_elem_dof = new Table(*scalar_ext[0]->GetBdrElementDofTable(),
                                  *scalar_ext[1]->GetElementDofTable(),ndofs1,
                                  *scalar_ext[2]->GetElementDofTable(),ndofs2,
                                  false );
      }
      else
      {
         mfem_error("FESpace implementation for  vector dimensions other then 2D/3D");
      }
   }
   else
   {
      ndofs = NURBSext->GetNDof();
      elem_dof = NURBSext->GetElementDofTable();
      bdr_elem_dof = NURBSext->GetBdrElementDofTable();
   }
   mesh_sequence = mesh->GetSequence();
   sequence++;
}

void FiniteElementSpace::BuildNURBSFaceToDofTable() const
{
   if (face_dof) { return; }

   const int dim = mesh->Dimension();

   // Find bdr to face mapping
   face_to_be.SetSize(GetNF());
   face_to_be = -1;
   for (int b = 0; b < GetNBE(); b++)
   {
      int f = mesh->GetBdrElementEdgeIndex(b);
      face_to_be[f] = b;
   }

   // Loop over faces in correct order, to prevent a sort
   // Sort will destroy orientation info in ordering of dofs
   Array<Connection> face_dof_list;
   Array<int> row;
   for (int f = 0; f < GetNF(); f++)
   {
      int b = face_to_be[f];
      if (b == -1) { continue; }
      // FIXME: this assumes that the boundary element and the face element have
      //        the same orientation.
      if (dim > 1)
      {
         const Element *fe = mesh->GetFace(f);
         const Element *be = mesh->GetBdrElement(b);
         const int nv = be->GetNVertices();
         const int *fv = fe->GetVertices();
         const int *bv = be->GetVertices();
         for (int i = 0; i < nv; i++)
         {
            MFEM_VERIFY(fv[i] == bv[i],
                        "non-matching face and boundary elements detected!");
         }

      else if (mesh->Dimension() == 3)
      {
         Array<int> newOrders0 = NURBSext->GetOrders();
         Array<int> newOrders1 = NURBSext->GetOrders();
         Array<int> newOrders2 = NURBSext->GetOrders();

         newOrders0[0] += 1;
         newOrders1[1] += 1;
         newOrders2[2] += 1;

         newOrders0.Print();
         newOrders1.Print();
         newOrders2.Print();

         scalar_ext.SetSize(3);
         scalar_fec.SetSize(3);
         scalar_fes.SetSize(3);

         scalar_ext[0] = new NURBSExtension(NURBSext, newOrders0);
         scalar_ext[1] = new NURBSExtension(NURBSext, newOrders1);
         scalar_ext[2] = new NURBSExtension(NURBSext, newOrders2);

         scalar_fec[0]  = new NURBSFECollection();
         scalar_fec[1]  = new NURBSFECollection();
         scalar_fec[2]  = new NURBSFECollection();

         scalar_fes[0] = new FiniteElementSpace(mesh, scalar_ext[0], scalar_fec[0]);
         scalar_fes[1] = new FiniteElementSpace(mesh, scalar_ext[1], scalar_fec[1]);
         scalar_fes[2] = new FiniteElementSpace(mesh, scalar_ext[2], scalar_fec[2]);

         int ndofs1 = scalar_ext[0]->GetNDof();
         int ndofs2 = scalar_ext[0]->GetNDof() +
                      scalar_ext[1]->GetNDof();

         ndofs = scalar_ext[0]->GetNDof() +
                 scalar_ext[1]->GetNDof() +
                 scalar_ext[2]->GetNDof();

         // Merge Tables
         elem_dof = new Table(*scalar_ext[0]->GetElementDofTable(),
                              *scalar_ext[1]->GetElementDofTable(),ndofs1,
                              *scalar_ext[2]->GetElementDofTable(),ndofs2);

         bdr_elem_dof = new Table(*scalar_ext[0]->GetBdrElementDofTable(),
                                  *scalar_ext[1]->GetElementDofTable(),ndofs1,
                                  *scalar_ext[2]->GetElementDofTable(),ndofs2,
                                  false );
      }

