    I.New(size+1);
    J.New(sum);

    I[0] = 0;
    for (i = 1; i <= size; i++)
    {
       I[i] = I[i-1] + connections_per_row;
       for (j = I[i-1]; j < I[i]; j++) { J[j] = -1; }
