+   auto &ob2 = poly1d.GetBasis(p - 1, BasisType::IntegratedGLL);
+   ob2.ScaleIntegrated(false);
+
+   Vector b;
+
+   // Evaluate cb2 at cb1
+   Bc_1d.SetSize(pp1*pp1);
+   Bct_1d.SetSize(pp1*pp1);
+   b.SetSize(pp1);
+   for (int i = 0; i < pp1; ++i)
+   {
+      cb2.Eval(cpts1[i], b);
+      for (int j = 0; j < pp1; ++j)
+      {
+         Bc_1d[i + j*pp1] = b[j];
+         Bct_1d[j + i*pp1] = b[j];
+      }
+   }
+
+   // Evaluate ob2 at ob1
+   Bo_1d.SetSize(p*p);
+   Bot_1d.SetSize(p*p);
+   b.SetSize(p);
+   for (int i = 0; i < p; ++i)
+   {
+      ob2.Eval(opts1[i], b);
+      for (int j = 0; j < p; ++j)
+      {
+         Bo_1d[i + j*p] = b[j];
+         Bot_1d[j + i*p] = b[j];
+      }
+   }
+
+   auto compute_inverse = [](const Array<double> &A, Array<double> &Ainv)
+   {
+      Array<double> A2 = A;
+      const int n2 = A.Size();
+      const int n = sqrt(n2);
+      Array<int> ipiv(n);
+      LUFactors lu(A2.GetData(), ipiv.GetData());
+      lu.Factor(n);
+      Ainv.SetSize(n2);
+      lu.GetInverseMatrix(n, Ainv.GetData());
+   };
+
+   compute_inverse(Bo_1d, Boi_1d);
+   compute_inverse(Bc_1d, Bci_1d);
+}
