+   for (int i = prolongations.Size() - 1; i >= 0; --i)
+   {
+      if (ownedProlongations[i])
+      {
+         delete prolongations[i];
+      }
+   }
+
+   operators.DeleteAll();
+   smoothers.DeleteAll();
+}
