+                  OpData<T> single_opd;
+                  single_opd.ldata = ldata;
+                  single_opd.buf = opd.buf + i;
+                  single_opd.ldofs = opd.ldofs + i;
+                  single_opd.nldofs = 1;
+                  single_opd.nb = opd.nb;
