 void GroupCommunicator::MaxAbs(OpData<T> opd)
 {
    for (int i = 0; i < opd.nldofs; i++)
    {
       T data = opd.ldata[opd.ldofs[i]];
       T abs_data = std::abs(data);

       for (int j = 0; j < opd.nb; j++)
       {
          T b = opd.buf[j*opd.nldofs+i];
          T abs_b = std::abs(b);

          if (abs_data < abs_b)
          {
             data = b;
             abs_data = abs_b;
          }
       }

       opd.ldata[opd.ldofs[i]] = data;
    }
 }

