+   for (int i = 0; i < 8; i++)
+   {
+      v[i].SetSize(3);
+      v[i] = 0.0;
+   }
+
+   for (int i = 0; i < center.Size(); i++)
+   {
+      v[0][i] = center[i];
+   }
+
+   Vector v_s(3); v_s = s;
