+   v[2][1] += 2*s;
+
+   v[3] = v[2];
+   v[3][0] -= 2*s;
+
+   Vector v_s_z({0.0,0.0,s});
+   for (int i = 4; i < 8; i++)
+   {
+      add(1.0, v[i-4], 2.0, v_s_z, v[i]);
+   }
+
+   for (int i = 0; i < 8; i++)
+   {
+      m.AddVertex(v[i]);
+   }
+
+   int vi[8];
+   for (int i = 0; i < 8; i++)
