+
+   for (int i = 0; i < pset.GetNP(); i++)
+   {
+      Vector pcoords;
+      pset.Coords().GetVectorValues(i, pcoords);
+      Add3DPoint(pcoords, particles_mesh, psize);
+   }
+   particles_mesh.FinalizeMesh();
+
+   FiniteElementSpace fes(&particles_mesh, &l2fec, 1);
+   GridFunction gf(&fes);
+
+   for (int i = 0; i < pset.GetNP(); i++)
