                                         DenseTensor &dE_ijk,
                                         DenseTensor &dphi_ijk,
                                         DenseTensor &VL_ijk,
                                         DenseMatrix &VR_ij,
                                         DenseMatrix &F) const
{
   real_t x = ip.x;
   real_t y = ip.y;
   real_t z = ip.z;
   Vector xy({x,y}), dmuz(3);
   real_t mu, muInv;

   if (std::fabs(1.0 - z) < 1e-4)
   {
      z = 1.0 - 1e-4;
      y = 0.5 * (1.0 - z);
      x = 0.5 * (1.0 - z);
      xy(0) = x; xy(1) = y;
   }

   Vector xy({x,y}), dmuz(3);
   real_t mu, muInv;

   if (std::fabs(1.0 - z) < 1e-4)
   {
      z = 1.0 - 1e-4;
      y = 0.5 * (1.0 - z);
      x = 0.5 * (1.0 - z);
