            {
               E(0) = E_ijk(i,j,0); E(1) = E_ijk(i,j,1); E(2) = E_ijk(i,j,2);
               dmuphi.cross3D(E, v);
               for (int l=0; l<3; l++)
               {
                  F(o, l) = muz * phi_k(k) * dE_ijk(i,j,l) + v(l);
