 {
    switch (problem)
    {
       case 1: // smooth field
          return x(1)+0.25*cos(2*M_PI*x.Norml2());
       case 2: // cubic function
          return x(1)*x(1)*x(1) + 2*x(0)*x(1) + x(0);
       case 3: // sharp gradient
          return M_PI/2-atan(5*(2*x.Norml2()-1));
       case 4: // basis function
          return (x.Norml2() < 0.1) ? 1 : 0;
       default:
          return 1.0;
    }
 }


