 void u_exact(const Vector & x, Vector & u)
 {
    double xi(x(0));
    double yi(x(1));
    double zi(x.Size() == 3 ? x(2) : 0.0);

    u(0) = - exp(xi)*sin(yi)*cos(zi);
    u(1) = - exp(xi)*cos(yi)*cos(zi);
    if (x.Size() == 3)
    {
       u(2) = exp(xi)*sin(yi)*sin(zi);
    }
 }

