+public:
+    KellyErrorEstimator(BilinearFormIntegrator& di_, ParGridFunction& sol_,
+                        ParFiniteElementSpace& flux_fespace_, 
+                        Array<int> attributes_ = Array<int>())
+        : attributes(attributes_)
+        , flux_integrator(&di_)
+        , solution(&sol_)
+        , flux_space(&flux_fespace_) 
+    {}
