NURBSExtension *FiniteElementSpace::StealNURBSext()
{
   if (NURBSext && !own_ext)
   {
      mfem_error("FiniteElementSpace::StealNURBSext");
   }
   own_ext = 0;

   return NURBSext;
}

void FiniteElementSpace::UpdateNURBS()
{
   MFEM_VERIFY(NURBSext, "NURBSExt not defined.");

   nvdofs = 0;
   nedofs = 0;
   nfdofs = 0;
   nbdofs = 0;
   bdofs = NULL;

   delete face_dof;
   face_dof = NULL;
   face_to_be.DeleteAll();

   dynamic_cast<const NURBSFECollection *>(fec)->Reset();

   if (dynamic_cast<const NURBS_HDivFECollection *>(fec))
   {
      if (mesh->Dimension() == 2)
      {
         component.SetSize(2);
         NURBSExtension* ext0 = NURBSext->DivElevate(0);
         NURBSExtension* ext1 = NURBSext->DivElevate(1);

         component[0] = new FiniteElementSpace(mesh, ext0, new NURBSFECollection());
         component[1] = new FiniteElementSpace(mesh, ext1, new NURBSFECollection());

         int offset1 = ext0->GetNDof();
         ndofs = ext0->GetNDof() + ext1->GetNDof();

         // Merge Tables
         elem_dof = new Table(*ext0->GetElementDofTable(),
                              *ext1->GetElementDofTable(),offset1 );

         bdr_elem_dof = new Table(*ext0->GetBdrElementDofTable(),
                                  *ext1->GetBdrElementDofTable(),offset1,
                                  false );
      }
      else if (mesh->Dimension() == 3)
      {
         component.SetSize(3);

         NURBSExtension* ext0 = NURBSext->DivElevate(0);
         NURBSExtension* ext1 = NURBSext->DivElevate(1);
         NURBSExtension* ext2 = NURBSext->DivElevate(2);

         component[0] = new FiniteElementSpace(mesh, ext0, new NURBSFECollection());
         component[1] = new FiniteElementSpace(mesh, ext1, new NURBSFECollection());
         component[2] = new FiniteElementSpace(mesh, ext2, new NURBSFECollection());

         int offset1 = ext0->GetNDof();
         int offset2 = offset1 + ext1->GetNDof();
         ndofs = offset2 + ext2->GetNDof();

         // Merge Tables
         elem_dof = new Table(*ext0->GetElementDofTable(),
                              *ext1->GetElementDofTable(),offset1,
                              *ext2->GetElementDofTable(),offset2);

         bdr_elem_dof = new Table(*ext0->GetBdrElementDofTable(),
                                  *ext1->GetBdrElementDofTable(),offset1,
                                  *ext2->GetBdrElementDofTable(),offset2,
                                  false );
      }
      else
      {
         mfem_error("FESpace implementation for  vector dimensions other then 2D/3D");
      }
   }
   else
   {
      ndofs = NURBSext->GetNDof();
      elem_dof = NURBSext->GetElementDofTable();
      bdr_elem_dof = NURBSext->GetBdrElementDofTable();
   }
   mesh_sequence = mesh->GetSequence();
   sequence++;
}

void FiniteElementSpace::BuildNURBSFaceToDofTable() const
{
   if (face_dof) { return; }

   const int dim = mesh->Dimension();

   // Find bdr to face mapping
   face_to_be.SetSize(GetNF());
   face_to_be = -1;
   for (int b = 0; b < GetNBE(); b++)
   {
      int f = mesh->GetBdrElementEdgeIndex(b);
      face_to_be[f] = b;
   }

   // Loop over faces in correct order, to prevent a sort
   // Sort will destroy orientation info in ordering of dofs
   Array<Connection> face_dof_list;
   Array<int> row;
   for (int f = 0; f < GetNF(); f++)
   {
      int b = face_to_be[f];
      if (b == -1) { continue; }
      // FIXME: this assumes that the boundary element and the face element have
      //        the same orientation.
      if (dim > 1)
      {
         const Element *fe = mesh->GetFace(f);
         const Element *be = mesh->GetBdrElement(b);
         const int nv = be->GetNVertices();
         const int *fv = fe->GetVertices();
         const int *bv = be->GetVertices();
         for (int i = 0; i < nv; i++)
         {
            MFEM_VERIFY(fv[i] == bv[i],
                        "non-matching face and boundary elements detected!");
         }

      else if (mesh->Dimension() == 3)
      {
         component.SetSize(3);

         NURBSExtension* ext0 = NURBSext->DivElevate(0);
         NURBSExtension* ext1 = NURBSext->DivElevate(1);
         NURBSExtension* ext2 = NURBSext->DivElevate(2);

         component[0] = new FiniteElementSpace(mesh, ext0, new NURBSFECollection());
         component[1] = new FiniteElementSpace(mesh, ext1, new NURBSFECollection());
         component[2] = new FiniteElementSpace(mesh, ext2, new NURBSFECollection());

         int offset1 = ext0->GetNDof();
         int offset2 = offset1 + ext1->GetNDof();
         ndofs = offset2 + ext2->GetNDof();

         // Merge Tables
         elem_dof = new Table(*ext0->GetElementDofTable(),
                              *ext1->GetElementDofTable(),offset1,
                              *ext2->GetElementDofTable(),offset2);

         bdr_elem_dof = new Table(*ext0->GetBdrElementDofTable(),
                                  *ext1->GetBdrElementDofTable(),offset1,
                                  *ext2->GetBdrElementDofTable(),offset2,
                                  false );
      }

