+void DGDiffusionBR2Integrator::AssembleFaceMatrix(
+   const FiniteElement &el1, const FiniteElement &el2,
+   FaceElementTransformations &Trans, DenseMatrix &elmat)
+{
+   int ndof1 = el1.GetDof();
+   shape1.SetSize(ndof1);
+
+   R11.SetSize(ndof1, ndof1);
+   R11 = 0.0;
+   MinvR11.SetSize(ndof1, ndof1);
+   M1inv.UseExternalData(Minv.GetData(Trans.Elem1No), ndof1, ndof1);
+
+   double factor = Geometries.NumBdr(Trans.Elem1->GetGeometryType());
+
+   int ndof2;
+   if (Trans.Elem2No >= 0)
+   {
+      ndof2 = el2.GetDof();
+      shape2.SetSize(ndof2);
+      R12.SetSize(ndof1, ndof2);
+      R21.SetSize(ndof2, ndof1);
+      R22.SetSize(ndof2, ndof2);
+      MinvR12.SetSize(ndof1, ndof2);
+      MinvR21.SetSize(ndof2, ndof1);
+      MinvR22.SetSize(ndof2, ndof2);
+      M2inv.UseExternalData(Minv.GetData(Trans.Elem2No), ndof2, ndof2);
+
+      R12 = 0.0;
+      R21 = 0.0;
+      R22 = 0.0;
+
+      factor = std::max(factor,
+         double(Geometries.NumBdr(Trans.Elem2->GetGeometryType())));
+   }
+   else
+   {
+      ndof2 = 0;
+   }
+
+   int ndofs = ndof1 + ndof2;
+
+   Re.SetSize(ndofs, ndofs);
+   MinvRe.SetSize(ndofs, ndofs);
+
+   elmat.SetSize(ndofs);
+   elmat = 0.0;
+
+   const IntegrationRule *ir = IntRule;
+   if (ir == NULL)
+   {
+      int order;
+      if (ndof2)
+      {
+         order = 2*max(el1.GetOrder(), el2.GetOrder());
+      }
+      else
+      {
+         order = 2*el1.GetOrder();
+      }
+      ir = &IntRules.Get(Trans.FaceGeom, order);
+   }
+
+   for (int p = 0; p < ir->GetNPoints(); p++)
+   {
+      const IntegrationPoint &ip = ir->IntPoint(p);
+      IntegrationPoint eip1, eip2;
+
+      Trans.Loc1.Transform(ip, eip1);
+      el1.CalcShape(eip1, shape1);
+      if (ndof2)
+      {
+         Trans.Loc2.Transform(ip, eip2);
+         el2.CalcShape(eip2, shape2);
+      }
+
+      double w = eta*ip.weight;
+      if (ndof2)
+      {
+         w /= 2;
+      }
+
+      // Create matrices corresponding to term <[u]{v}>
+      for (int i = 0; i < ndof1; i++)
+      {
+         const double wsi = w*shape1(i);
+         for (int j = 0; j < ndof1; j++)
+         {
+            R11(i, j) += wsi * shape1(j);
+         }
+      }
+
+      if (ndof2)
+      {
+         for (int i = 0; i < ndof2; i++)
+         {
+            const double wsi = w*shape2(i);
+            for (int j = 0; j < ndof1; j++)
+            {
+               R21(i, j) += wsi * shape1(j);
+               R12(j, i) -= wsi * shape1(j);
+            }
+            for (int j = 0; j < ndof2; j++)
+            {
+               R22(i, j) -= wsi * shape2(j);
+            }
+         }
+      }
+   }
+
+   Mult(M1inv, R11, MinvR11);
+   for (int i = 0; i < ndof1; i++)
+   {
+      for (int j = 0; j < ndof1; j++)
+      {
+         Re(i, j) = R11(i, j);
+         MinvRe(i, j) = MinvR11(i, j);
+      }
+   }
+
+   if (ndof2)
+   {
+      Mult(M1inv, R12, MinvR12);
+      Mult(M2inv, R21, MinvR21);
+      Mult(M2inv, R22, MinvR22);
+
+      for (int i = 0; i < ndof2; i++)
+      {
+         for (int j = 0; j < ndof1; j++)
+         {
+            Re(ndof1 + i, j) = R21(i, j);
+            MinvRe(ndof1 + i, j) = MinvR21(i, j);
+
+            Re(j, ndof1 + i) = R12(j, i);
+            MinvRe(j, ndof1 + i) = MinvR12(j, i);
+         }
+         for (int j = 0; j < ndof2; j++)
+         {
+            Re(ndof1 + i, ndof1 + j) = R22(i, j);
+            MinvRe(ndof1 + i, ndof1 + j) = MinvR22(i, j);
+         }
+      }
+   }
+
+   MultAtB(Re, MinvRe, elmat);
+}

