 double SPDESolver::ConstructNormalizationCoefficient(double nu, double l1,
                                                      double l2, double l3,
                                                      int dim) {
   // Computation considers squaring components, computing determinant, and
   // squaring
   double det = 0;
   if (dim == 1) {
