   } else if (dim == 2) {
     det = l1 * l2;
   } else if (dim == 3) {
     det = l1 * l2 * l3;
   }
   const double gamma1 = tgamma(nu + static_cast<double>(dim) / 2.0);
   const double gamma2 = tgamma(nu);
   return sqrt(pow(2 * M_PI, dim / 2.0) * det * gamma1 /
               (gamma2 * pow(nu, dim / 2.0)));
