void MinimumDiscardFillOrdering(SparseMatrix &C, Array<int> &p)
{
   int n = C.Width();
   // Scale rows by reciprocal of diagonal and take absolute value
   Vector D;
   C.GetDiag(D);
   int *I = C.GetI();
   int *J = C.GetJ();
   double *V = C.GetData();
   for (int i=0; i<n; ++i)
   {
      for (int j=I[i]; j<I[i+1]; ++j)
      {
         V[j] = abs(V[j]/D[i]);
      }
   }

   std::vector<double> w(n, 0.0);
   // Compute the discarded-fill weights
   for (int ik=0; ik<n; ++ik)
   {
      for (int i=I[ik]; i<I[ik+1]; ++i)
      {
         int ji = J[i];
         double val;
         for (int j=I[ji]; j<I[ji+1]; ++j)
         {
            if (J[j] == ik)
            {
               val = V[j];
               break;
            }
         }
         for (int j=I[ik]; j<I[ik+1]; ++j)
         {
            int jj = J[j];
            if (ji == jj) { continue; }
            w[ik] += pow(val*V[j], 2);
         }
      }
      w[ik] = sqrt(w[ik]);
   }

   WeightMinHeap w_heap(w);

   // Compute ordering
   p.SetSize(n);
   for (int ii=0; ii<n; ++ii)
   {
      int pi = w_heap.pop();
      p[ii] = pi;
      w[pi] = -1;
      for (int k=I[pi]; k<I[pi+1]; ++k)
      {
         int ik = J[k];
         if (w_heap.picked(ik)) { continue; }
         // Recompute weight
         w[ik] = 0.0;
         for (int i=I[ik]; i<I[ik+1]; ++i)
         {
            int ji = J[i];
            if (w_heap.picked(ji)) { continue; }
            double val;
            for (int j=I[ji]; j<I[ji+1]; ++j)
            {
               if (J[j] == ik)
               {
                  val = V[j];
                  break;
               }
            }
            for (int j=I[ik]; j<I[ik+1]; ++j)
            {
               int jj = J[j];
               // Ignore entries we have already chosen
               if (ji == jj || w_heap.picked(jj)) { continue; }
               w[ik] += pow(val*V[j], 2);
            }
         }
         w[ik] = sqrt(w[ik]);
         w_heap.update(ik);
