    {
       switch ((D1D << 4 ) | Q1D)
       {
          case 0x23: return PADGDiffusionApply2D<2,3>(NF,B,Bt,G,Gt,sigma,kappa,pa_data,x,
                                                         dxdn,y,dydn);
